/**
 * Integrations connect Gorgias with external services (e.g. Gmail, Shopify, chat systems).  There are official Gorgias integrations that can be found in the Integrations page in the helpdesk and there are custom HTTP integrations.  Most integrations use HTTP APIs.
 * @export
 * @interface Integration
 */
export interface Integration {
    /**
     * ID of the integration.
     * @type {number}
     * @memberof Integration
     */
    id?: number
    /**
     * When the integration was created.
     * @type {string}
     * @memberof Integration
     */
    created_datetime?: string | null
    /**
     * When the integration was deactivated.
     * @type {string}
     * @memberof Integration
     */
    deactivated_datetime?: string | null
    /**
     * Description about the integration.
     * @type {string}
     * @memberof Integration
     */
    description?: string | null
    /**
     *
     * @type {IntegrationHttp}
     * @memberof Integration
     */
    http?: IntegrationHttp | null
    /**
     * Name of the integration. Usually the email address, Facebook page name, etc.
     * @type {string}
     * @memberof Integration
     */
    name: string
    /**
     * Type of integration.
     * @type {string}
     * @memberof Integration
     */
    type?: IntegrationTypeEnum
    /**
     * When the integration was last updated.
     * @type {string}
     * @memberof Integration
     */
    updated_datetime?: string | null
    /**
     *
     * @type {IntegrationUser}
     * @memberof Integration
     */
    user?: IntegrationUser
    /**
     * URI of the integration.
     * @type {string}
     * @memberof Integration
     */
    uri?: string
    /**
     * ID of the related application.
     * @type {string}
     * @memberof Integration
     */
    application_id?: string | null
}

export const IntegrationTypeEnum = {
    Http: 'http',
} as const

export type IntegrationTypeEnum = typeof IntegrationTypeEnum[keyof typeof IntegrationTypeEnum]

/**
 * Only available for HTTP integrations, defines the configuration of the integration.
 * @export
 * @interface IntegrationHttp
 */
export interface IntegrationHttp {
    /**
     * Data to send to the external service. It can either be a raw JSON object (if `request_content_type` is `application/json`) or a key-value object representing form data (if `request_content_type` is `application/x-www-form-urlencoded`). You can use variables like {{ticket.customer.email}} as values for the request. Check all properties from a [customer](#the-customer-object), or review the list of [Gorgias variables](https://docs.gorgias.com/macros/macro-variables#gorgias_variables) for inspiration.
     * @type {any}
     * @memberof IntegrationHttp
     */
    form?: any | null
    /**
     * HTTP method expected by the external service.
     * @type {string}
     * @memberof IntegrationHttp
     */
    method?: IntegrationHttpMethodEnum
    /**
     * Content type of the outgoing request to the external service.
     * @type {string}
     * @memberof IntegrationHttp
     */
    request_content_type?: IntegrationHttpRequestContentTypeEnum
    /**
     * Content type of the incoming response from the external service.
     * @type {string}
     * @memberof IntegrationHttp
     */
    response_content_type?: IntegrationHttpResponseContentTypeEnum
    /**
     *
     * @type {CreateIntegrationRequestHttpTriggers}
     * @memberof IntegrationHttp
     */
    triggers?: CreateIntegrationRequestHttpTriggers
    /**
     * URL of the external service. You can use variables like {{ticket.customer.email}} to pass customer data to the integration. Check all properties from a [customer](#the-customer-object), or review the list of [Gorgias variables](https://docs.gorgias.com/macros/macro-variables#gorgias_variables) for inspiration.
     * @type {string}
     * @memberof IntegrationHttp
     */
    url: string
}

