/**
 * A client class for Gorgias, extending AllApis.
 * @export
 */
export class GorgiasClient extends AllApis {
    constructor(abortController?: AbortController) {
        let configParams: ConfigurationParameters

        if (process.env.PAN_SEC_GORGIAS_OAUTH_ACCESS_TOKEN) {
            configParams = {
                basePath: `https://${process.env.PAN_SEC_GORGIAS_OAUTH_ACCOUNT}.gorgias.com`,
                accessToken: process.env.PAN_SEC_GORGIAS_OAUTH_ACCESS_TOKEN,
                abortController,
            }
        } else {
            configParams = {
                basePath: process.env.PAN_SEC_GORGIAS_STORE_NAME?.slice(0, -5), // remove '/api/' from the end of the storeName
                username: process.env.PAN_SEC_GORGIAS_EMAIL,
                password: process.env.PAN_SEC_GORGIAS_API_KEY,
                abortController,
            }
        }

        const config = new Configuration(configParams)
        super(config)
    }
}
